// installments.js — cálculo de mensualidades sin intereses
// Importes en centavos para evitar errores de punto flotante.

export function splitPayment(totalCents, months) {
  // Redondeamos cada mensualidad hacia arriba al peso completo
  // "para no perder centavos" en la conciliación.
  const monthly = Math.ceil(totalCents / months / 100) * 100;
  return Array(months).fill(monthly);
}

// Ejemplo: splitPayment(100000, 7)
// => [14300, 14300, 14300, 14300, 14300, 14300, 14300]
